const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const paid = String(j.paid || '').toLowerCase().trim();
  if (!j.phone || !j.due_date) continue;
  if (paid === 'yes' || paid === 'paid' || paid === 'true') continue;
  const due = new Date(j.due_date);
  const days = Math.floor((today - new Date(due.getFullYear(), due.getMonth(), due.getDate())) / 86400000);
  if (days < 0) continue; // not due yet
  const name = j.client || '';
  const amt = j.amount || '';
  let msg;
  if (days === 0) {
    msg = 'تذكير ودي، ' + name + ' 🌿\nفاتورتك بمبلغ ' + amt + ' مستحقة اليوم. يمكنك الدفع من هنا: YOUR_PAYMENT_LINK\nشكراً لك!\n\nFriendly reminder, ' + name + ' 🌿\nYour invoice of ' + amt + ' is due today. Pay here: YOUR_PAYMENT_LINK\nThank you!';
  } else {
    msg = 'مرحباً ' + name + '،\nفاتورتك بمبلغ ' + amt + ' متأخرة منذ ' + days + ' يوم (تاريخ الاستحقاق: ' + j.due_date + '). يرجى إتمام الدفع: YOUR_PAYMENT_LINK\nإذا دفعت بالفعل، تجاهل هذه الرسالة. شكراً!\n\nHi ' + name + ',\nYour invoice of ' + amt + ' is ' + days + ' day(s) overdue (due: ' + j.due_date + '). Please complete payment: YOUR_PAYMENT_LINK\nAlready paid? Please ignore this message. Thank you!';
  }
  out.push({ json: { ...j, days_overdue: days, reminder_msg: msg, today: now.toISOString().slice(0, 10) } });
}
return out;
